CREATE TYPE "BookingStatus" AS ENUM (
  'RESERVED',
  'PAYMENT_REVIEW',
  'BOOKED',
  'CANCELLED'
);

CREATE TYPE "PaymentStatus" AS ENUM (
  'PENDING',
  'PAID',
  'FAILED',
  'CANCELLED'
);

CREATE TYPE "PaymentMethod" AS ENUM (
  'CARD',
  'MPESA'
);

CREATE TYPE "PaymentInitializationStatus" AS ENUM (
  'QUEUED',
  'SUBMITTING',
  'READY',
  'PAID',
  'FAILED',
  'REJECTED',
  'UNKNOWN',
  'CANCELLED',
  'REVIEW_REQUIRED'
);

CREATE TABLE "auditoriums" (
  "id" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "name" varchar NOT NULL,
  "created_at" timestamptz NOT NULL
);

CREATE TABLE "movies" (
  "id" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "name" varchar NOT NULL,
  "description" varchar NOT NULL,
  "runtime_minutes" integer NOT NULL,
  "created_at" timestamptz NOT NULL,
  CONSTRAINT "movies_runtime_positive" CHECK (runtime_minutes > 0)
);

CREATE TABLE "screenings" (
  "id" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "movie_id" integer NOT NULL,
  "auditorium_id" integer NOT NULL,
  "currency" varchar(3) NOT NULL,
  "start_time" timestamptz NOT NULL,
  "end_time" timestamptz NOT NULL,
  "created_at" timestamptz NOT NULL,
  CONSTRAINT "screenings_end_after_start" CHECK (end_time > start_time)
);

CREATE TABLE "seats" (
  "id" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "label" varchar NOT NULL,
  "auditorium_id" integer NOT NULL,
  "created_at" timestamptz NOT NULL
);

CREATE TABLE "screening_seats" (
  "screening_id" integer NOT NULL,
  "seat_id" integer NOT NULL,
  "auditorium_id" integer NOT NULL,
  "price_amount" integer NOT NULL,
  CONSTRAINT "screening_seats_price_positive" CHECK (price_amount > 0),
  PRIMARY KEY ("screening_id", "seat_id")
);

CREATE TABLE "bookings" (
  "id" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "booking_reference" varchar UNIQUE NOT NULL,
  "idempotency_key" varchar NOT NULL UNIQUE,
  "request_fingerprint" varchar NOT NULL,
  "customer_email" varchar NOT NULL,
  "customer_phone" varchar NOT NULL,
  "status" "BookingStatus" NOT NULL,
  "screening_id" integer NOT NULL,
  "hold_expires_at" timestamptz NOT NULL,
  "created_at" timestamptz NOT NULL,
  CONSTRAINT "bookings_hold_expires_after_creation" CHECK (hold_expires_at > created_at)
);

CREATE TABLE "payment_attempts" (
  "id" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "booking_id" integer UNIQUE NOT NULL,
  "status" "PaymentStatus" NOT NULL,
  "amount" integer NOT NULL,
  "currency" varchar(3) NOT NULL,
  "created_at" timestamptz NOT NULL,
  CONSTRAINT "payment_attempts_amount_positive" CHECK (amount > 0)
);

CREATE TABLE "payment_initializations" (
  "id" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "payment_attempt_id" integer NOT NULL,
  "paystack_reference" varchar UNIQUE NOT NULL,
  "payment_method" "PaymentMethod" NOT NULL,
  "authorization_url" varchar,
  "status" "PaymentInitializationStatus" NOT NULL,
  "rejection_reason" varchar,
  "worker_attempt_count" integer NOT NULL DEFAULT 0,
  "next_attempt_at" timestamptz,
  "lease_expires_at" timestamptz,
  "created_at" timestamptz NOT NULL,
  "updated_at" timestamptz NOT NULL,
  CONSTRAINT "payment_initializations_attempt_count_nonnegative"
    CHECK (worker_attempt_count >= 0),
  CONSTRAINT "payment_initializations_submitting_requires_lease"
    CHECK ((status = 'SUBMITTING') = (lease_expires_at IS NOT NULL))
);

CREATE TABLE "payment_initialization_receipts" (
  "idempotency_key" varchar PRIMARY KEY,
  "request_fingerprint" varchar NOT NULL,
  "requested_payment_method" "PaymentMethod" NOT NULL,
  "payment_initialization_id" integer NOT NULL REFERENCES "payment_initializations" ("id") ON DELETE CASCADE,
  "created_at" timestamptz NOT NULL DEFAULT clock_timestamp()
);

CREATE TABLE "bookings_seats" (
  "booking_id" integer NOT NULL,
  "seat_id" integer NOT NULL,
  "screening_id" integer NOT NULL,
  "unit_price_amount" integer NOT NULL,
  "currency" varchar(3) NOT NULL,
  CONSTRAINT "bookings_seats_price_positive" CHECK (unit_price_amount > 0),
  PRIMARY KEY ("booking_id", "seat_id")
);

CREATE TABLE "seat_claims" (
  "screening_id" integer NOT NULL,
  "seat_id" integer NOT NULL,
  "booking_id" integer NOT NULL,
  PRIMARY KEY ("screening_id", "seat_id")
);

CREATE UNIQUE INDEX ON "screenings" ("id", "auditorium_id");

CREATE UNIQUE INDEX "screenings_id_currency_unique" ON "screenings" ("id", "currency");

CREATE UNIQUE INDEX ON "seats" ("id", "auditorium_id");

CREATE UNIQUE INDEX ON "seats" ("auditorium_id", "label");

CREATE UNIQUE INDEX ON "bookings" ("id", "screening_id");

CREATE INDEX ON "payment_initializations" ("payment_attempt_id");

CREATE INDEX "payment_initializations_due_work"
ON "payment_initializations" ("next_attempt_at", "id")
WHERE "status" IN ('QUEUED', 'UNKNOWN', 'READY');

CREATE INDEX "payment_initializations_expired_leases"
ON "payment_initializations" ("lease_expires_at", "id")
WHERE "status" = 'SUBMITTING';

CREATE UNIQUE INDEX "one_unresolved_initialization_per_payment_attempt"
ON payment_initializations(payment_attempt_id)
WHERE status IN ('QUEUED', 'SUBMITTING', 'READY', 'UNKNOWN', 'REVIEW_REQUIRED');

COMMENT ON COLUMN "screening_seats"."price_amount" IS 'Stored in minor currency units';

COMMENT ON COLUMN "screenings"."currency" IS 'Currency used by all seat prices for this screening';

COMMENT ON COLUMN "payment_attempts"."amount" IS 'Stored in minor currency units';

COMMENT ON COLUMN "payment_attempts"."currency" IS 'Three-letter currency code, e.g. KES';

COMMENT ON COLUMN "payment_initializations"."paystack_reference" IS 'Generated and persisted before calling Paystack';

COMMENT ON COLUMN "payment_initializations"."authorization_url" IS 'Nullable until Paystack returns hosted checkout details';

COMMENT ON COLUMN "payment_initialization_receipts"."request_fingerprint" IS 'Compared on idempotency replay; not unique';

COMMENT ON COLUMN "payment_initializations"."worker_attempt_count" IS 'Incremented whenever a worker claims this job';

COMMENT ON COLUMN "payment_initializations"."lease_expires_at" IS 'Allows recovery if a worker crashes while SUBMITTING';

COMMENT ON COLUMN "bookings_seats"."unit_price_amount" IS 'Price snapshot in minor currency units';

COMMENT ON COLUMN "bookings_seats"."currency" IS 'Currency snapshot for this booking seat';

ALTER TABLE "screenings" ADD FOREIGN KEY ("movie_id") REFERENCES "movies" ("id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "screenings" ADD FOREIGN KEY ("auditorium_id") REFERENCES "auditoriums" ("id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "seats" ADD FOREIGN KEY ("auditorium_id") REFERENCES "auditoriums" ("id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "bookings" ADD FOREIGN KEY ("screening_id") REFERENCES "screenings" ("id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "payment_attempts" ADD FOREIGN KEY ("booking_id") REFERENCES "bookings" ("id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "payment_initializations" ADD FOREIGN KEY ("payment_attempt_id") REFERENCES "payment_attempts" ("id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "screening_seats" ADD FOREIGN KEY ("screening_id", "auditorium_id") REFERENCES "screenings" ("id", "auditorium_id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "screening_seats" ADD FOREIGN KEY ("seat_id", "auditorium_id") REFERENCES "seats" ("id", "auditorium_id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "bookings_seats" ADD FOREIGN KEY ("booking_id", "screening_id") REFERENCES "bookings" ("id", "screening_id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "bookings_seats" ADD FOREIGN KEY ("screening_id", "seat_id") REFERENCES "screening_seats" ("screening_id", "seat_id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "bookings_seats" ADD CONSTRAINT "bookings_seats_screening_currency_fkey"
  FOREIGN KEY ("screening_id", "currency") REFERENCES "screenings" ("id", "currency") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "seat_claims" ADD FOREIGN KEY ("booking_id", "seat_id") REFERENCES "bookings_seats" ("booking_id", "seat_id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "seat_claims" ADD FOREIGN KEY ("booking_id", "screening_id") REFERENCES "bookings" ("id", "screening_id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "seat_claims" ADD FOREIGN KEY ("screening_id", "seat_id") REFERENCES "screening_seats" ("screening_id", "seat_id") DEFERRABLE INITIALLY IMMEDIATE;
